python - <<'PY'
import numpy as np
exp_info=np.load('/app/data/beh/Imaging_Exp_info.npy', allow_pickle=True).item()
seen={}
for exp_type, arr in exp_info.items():
    beh=np.load(f'/app/data/beh/Beh_{exp_type}.npy', allow_pickle=True).item()
    for rec in arr:
        base=f"{rec['mname']}_{rec['datexp']}_{rec['blk']}"
        if base in seen:
            continue
        key=base + (f"_{rec['stimtype']}" if 'stimtype' in rec else '')
        sess=beh[key]
        dt=np.median(np.diff(sess['ft']))*24*3600
        seen[base]=(dt, exp_type, key)
for base,(dt,exp_type,key) in sorted(seen.items(), key=lambda x:x[1][0])[:10]:
    print('small', dt, exp_type, key)
for base,(dt,exp_type,key) in sorted(seen.items(), key=lambda x:x[1][0], reverse=True)[:10]:
    print('large', dt, exp_type, key)
